"""C3 robustness: is "the support region refuses what ancestry bounds accept" an artefact of one
particular support-region configuration, or of the restricted marker set?

**Post-hoc and non-confirmatory.** C3 was generated by a diagnosis run after the frozen 6C2 endpoint
failed, so nothing here can confirm it; a sensitivity map can only show whether it is fragile.
Confirmation needs a second out-of-reference population scored under a rule fixed in advance.

Part A - support-rule sensitivity map. Over k x n_support_components x radius percentile, report

    R_external = P(the 99 out-of-reference dairy animals are refused)
    R_florida  = P(Florida held-out animals are falsely refused)

C3 is fragile if a large separation R_external >> R_florida holds only near the default
configuration. The min-max ancestry comparator is reported once, since it depends on none of these.

Part B - projection-coordinate stability. The two-reference estimator cannot express "not an
Angus-Brahman animal": it projects an out-of-reference genome onto the Angus<->Brahman axis. So the
0.18 figure is reported here as q_AB_axis, a coordinate, never as a Brahman ancestry fraction.
Repeated marker subsamples show whether the coordinate itself is stable, which is a different and
weaker claim than ancestry.

Everything is fitted on Florida training animals only.
"""
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "scripts"))

from src.evaluation.ood_detector import GenomicOODDetector  # noqa: E402
from src.evaluation.risk_calibration import load_frozen_thresholds  # noqa: E402
from src.real_data.ancestry_estimation import breed_frequencies, estimate_brahman_fraction  # noqa: E402
from src.real_data.canonical_split import CanonicalDataSplitter  # noqa: E402
from run_layer6c2_hairy_probe import harmonise, read_bed_dosages, PLINK  # noqa: E402
from run_layer6c_external_validation import FloridaReference  # noqa: E402

OUT = ROOT / "output/layer6c2"
THRESH = ROOT / "output/ood_calibration/thresholds_rev1.json"
K_GRID = [5, 10, 20, 40, 80]
PC_GRID = [5, 10, 20, 30]
LEVEL_GRID = [0.90, 0.95, 0.975, 0.99]
SUBSAMPLE_SHARES = [0.5, 0.6, 0.7, 0.8]
N_SUBSAMPLES, SEED = 200, 20260912


def build_matrices():
    """Florida training, Florida held-out and external genotypes in the shared-marker subspace."""
    ref = FloridaReference()
    _, keep, stats = harmonise()
    cols = {m: i for i, m in enumerate(ref.markers)}
    idx = np.array([cols[m] for m in keep["marker"]])
    pos = {a: i for i, a in enumerate(ref.ids)}

    tr = np.array([pos[a] for a in ref.train_ids])
    G_tr = ref.snp[tr][:, idx]
    mean_sub = np.nanmean(G_tr, axis=0)
    G_tr = np.where(np.isnan(G_tr), mean_sub, G_tr)

    split = CanonicalDataSplitter.get_prospective_split("AvgShortLength", valid_animal_ids=ref.ids,
                                                        require_joint_traits=True)
    te = np.array([pos[a] for a in split.test_ids])
    G_fl = np.where(np.isnan(ref.snp[te][:, idx]), mean_sub, ref.snp[te][:, idx])

    fam = pd.read_csv(f"{PLINK}.fam", sep=r"\s+", header=None,
                      names=["fid", "iid", "pid", "mid", "sex", "phenotype"], dtype=str)
    G_ext = read_bed_dosages(keep, len(fam))
    G_ext = np.where(np.isnan(G_ext), mean_sub, G_ext)

    pa_full, pb_full, _, _ = breed_frequencies(ref.snp, ref.boa)
    return {"G_tr": G_tr, "G_fl": G_fl, "G_ext": G_ext, "idx": idx,
            "p_angus": pa_full[idx], "p_brahman": pb_full[idx],
            "coverage": stats["coverage"], "n_markers": len(idx)}


def sensitivity_map(M):
    thr = load_frozen_thresholds(THRESH)
    q_tr = estimate_brahman_fraction(M["G_tr"], M["p_angus"], M["p_brahman"])
    q_ext = estimate_brahman_fraction(M["G_ext"], M["p_angus"], M["p_brahman"])
    q_fl = estimate_brahman_fraction(M["G_fl"], M["p_angus"], M["p_brahman"])

    # the comparator C3 is about: min-max bounds on the training ancestry coordinate
    lo, hi = float(q_tr.min()), float(q_tr.max())
    comparator = {
        "rule": "min-max ancestry bounds on the training Angus-Brahman coordinate",
        "training_range": [round(lo, 4), round(hi, 4)],
        "external_refused_share": round(float(np.mean((q_ext < lo) | (q_ext > hi))), 4),
        "florida_refused_share": round(float(np.mean((q_fl < lo) | (q_fl > hi))), 4),
        "depends_on_k_pc_or_level": False,
    }
    print(f"min-max ancestry comparator: external refused "
          f"{comparator['external_refused_share']:.3f}, Florida refused {comparator['florida_refused_share']:.3f}")

    rows = []
    for pc in PC_GRID:
        for k in K_GRID:
            for level in LEVEL_GRID:
                det = GenomicOODDetector(
                    n_components=15, n_support_components=pc, support_k=k, support_level=level,
                    calibrated_thresholds={"ranking": thr["ranking"], "absolute": thr["absolute"]})
                det.fit(M["G_tr"], ancestry_qb_train=q_tr, env_ids_train=["Semin"] * len(M["G_tr"]))
                ext = det.assess_cohort(M["G_ext"], ancestry_qb_cohort=q_ext,
                                        env_ids_cohort=["LittlejohnNZ"] * len(M["G_ext"]))
                fl = det.assess_cohort(M["G_fl"], ancestry_qb_cohort=q_fl,
                                       env_ids_cohort=["Willi"] * len(M["G_fl"]))
                rows.append({
                    "k": k, "n_support_components": pc, "support_level": level,
                    "R_external_rule": round(float(np.mean([not a.allow_ranking_only for a in ext])), 4),
                    "R_florida_rule": round(float(np.mean([not a.allow_ranking_only for a in fl])), 4),
                    "median_support_external": round(float(np.median([a.support_score for a in ext])), 4),
                    "median_support_florida": round(float(np.median([a.support_score for a in fl])), 4),
                })
                print(f"  [{len(rows):>2}/{len(PC_GRID)*len(K_GRID)*len(LEVEL_GRID)}] "
                      f"k={k:>3} pc={pc:>3} level={level:<6} "
                      f"R_ext={rows[-1]['R_external_rule']:.3f}  R_fl={rows[-1]['R_florida_rule']:.3f}",
                      flush=True)
                # written every iteration so an interrupted grid is not lost
                OUT.mkdir(parents=True, exist_ok=True)
                pd.DataFrame(rows).to_csv(OUT / "c3_sensitivity_map.csv", index=False)
    return comparator, rows


def coordinate_stability(M):
    """Does the Angus-Brahman projection coordinate survive marker subsampling?"""
    rng = np.random.default_rng(SEED)
    full_ext = estimate_brahman_fraction(M["G_ext"], M["p_angus"], M["p_brahman"])
    out = {"full_panel_mean_q_AB_axis": round(float(full_ext.mean()), 4), "subsamples": {}}
    n = M["n_markers"]
    for share in SUBSAMPLE_SHARES:
        means = []
        for _ in range(N_SUBSAMPLES):
            sel = rng.choice(n, size=int(round(share * n)), replace=False)
            means.append(float(estimate_brahman_fraction(
                M["G_ext"][:, sel], M["p_angus"][sel], M["p_brahman"][sel]).mean()))
        means = np.array(means)
        out["subsamples"][f"{int(share*100)}%"] = {
            "mean": round(float(means.mean()), 4), "sd": round(float(means.std(ddof=1)), 4),
            "p2.5": round(float(np.percentile(means, 2.5)), 4),
            "p97.5": round(float(np.percentile(means, 97.5)), 4)}
        print(f"  markers {int(share*100):>3}%: q_AB_axis mean {means.mean():.4f} "
              f"sd {means.std(ddof=1):.4f} [{np.percentile(means, 2.5):.4f}, {np.percentile(means, 97.5):.4f}]")
    return out


def main():
    M = build_matrices()
    print(f"shared subspace: {M['n_markers']:,} markers ({100*M['coverage']:.1f}% of the panel)\n")

    print("Part A - support-rule sensitivity map")
    comparator, rows = sensitivity_map(M)
    df = pd.DataFrame(rows)
    sep = df["R_external_rule"] - df["R_florida_rule"]
    summary = {
        "n_configurations": len(df),
        "R_external_min": round(float(df["R_external_rule"].min()), 4),
        "R_external_median": round(float(df["R_external_rule"].median()), 4),
        "R_florida_max": round(float(df["R_florida_rule"].max()), 4),
        "R_florida_median": round(float(df["R_florida_rule"].median()), 4),
        "separation_min": round(float(sep.min()), 4),
        "separation_median": round(float(sep.median()), 4),
        "configs_with_full_external_refusal": int((df["R_external_rule"] >= 0.999).sum()),
        "configs_with_separation_above_0.5": int((sep > 0.5).sum()),
        "configs_where_conclusion_reverses": int((sep <= 0).sum()),
    }

    print("\nPart B - projection-coordinate stability under marker subsampling")
    stability = coordinate_stability(M)

    fragile = summary["configs_with_separation_above_0.5"] < len(df)
    result = {
        "utc": datetime.now(timezone.utc).isoformat(timespec="seconds"), "evidence": "EMPIRICAL",
        "status": "POST_HOC_SUPPORTED - robustness check, not confirmation",
        "claim_under_test": "C3: the k-NN support region refuses a population the min-max ancestry bounds accept",
        "why_this_cannot_confirm": (
            "C3 was generated by a post-hoc diagnosis after the frozen endpoint failed. A sensitivity map "
            "over the same animals can show fragility but cannot supply pre-registered confirmation; that "
            "needs a second out-of-reference population under a rule fixed before its scores are seen."),
        "shared_markers": M["n_markers"], "coverage": M["coverage"],
        "ancestry_comparator": comparator,
        "grid": {"k": K_GRID, "n_support_components": PC_GRID, "support_level": LEVEL_GRID},
        "summary": summary,
        "configurations": rows,
        "projection_coordinate_stability": stability,
        "terminology": (
            "q_AB_axis is the coordinate of a genome on the Angus<->Brahman axis under a two-reference "
            "supervised model. For a population that is neither Angus nor Brahman it is NOT a Brahman "
            "ancestry fraction, and must not be reported as one. Its stability under marker subsampling "
            "says the coordinate is reproducible, not that the ancestry is real."),
        "verdict": ("separation holds across the whole grid" if not fragile else
                    "separation does not hold across the whole grid - see configs_with_separation_above_0.5"),
    }
    (OUT / "results_6c2_c3_robustness.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
    df.to_csv(OUT / "c3_sensitivity_map.csv", index=False)
    print(f"\nconfigurations: {summary['n_configurations']}   "
          f"separation > 0.5 in {summary['configs_with_separation_above_0.5']}   "
          f"conclusion reverses in {summary['configs_where_conclusion_reverses']}")
    print(f"R_external median {summary['R_external_median']:.3f} (min {summary['R_external_min']:.3f}); "
          f"R_florida median {summary['R_florida_median']:.3f} (max {summary['R_florida_max']:.3f})")
    print(f"wrote {(OUT / 'results_6c2_c3_robustness.json').relative_to(ROOT)}")


if __name__ == "__main__":
    main()
